PAYLOADS = ["' OR '1'='1", "admin' --", "'; DROP TABLE users; --", "x' UNION SELECT password,1 FROM users --"]

@pytest.mark.parametrize("payload", PAYLOADS)
def test_sql_payloads_are_just_data(db, payload):
    assert find_user(db, payload) == []          # nenhuma linha tem esse nome literal
    assert db.execute("SELECT count(*) FROM users").fetchone()[0] > 0   # a tabela continua existindo

def test_ping_rejects_shell_metacharacters():
    with pytest.raises(ValueError):
        ping("example.com; cat /etc/passwd")

def test_html_is_escaped(client):
    body = client.get("/hello?name=<script>alert(1)</script>").text
    assert "<script>" not in body and "&lt;script&gt;" in body
